def background(grid):
    """The most common color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def bbox(grid, bg=None, skip=()):
    """(r0, r1, c0, c1) of the non-background, non-skip cells."""
    bg = background(grid) if bg is None else bg
    pts=[(i,j) for i,row in enumerate(grid) for j,v in enumerate(row) if v!=bg and v not in skip]
    return min(i for i,j in pts), max(i for i,j in pts), min(j for i,j in pts), max(j for i,j in pts)

def complete_dashed(grid, new=2, thresh=4):
    """Fill background cells on a dashed line (row/col with >= thresh shape cells) inside the shape's bounding box, with new."""
    from collections import Counter
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    shape=lambda v: v!=bg and v!=new
    pts=[(i,j) for i in range(h) for j in range(w) if shape(grid[i][j])]
    if not pts: return [row[:] for row in grid]
    r0,r1=min(i for i,j in pts),max(i for i,j in pts)
    c0,c1=min(j for i,j in pts),max(j for i,j in pts)
    rows={i for i in range(h) if sum(shape(v) for v in grid[i])>=thresh}
    cols={j for j in range(w) if sum(shape(grid[i][j]) for i in range(h))>=thresh}
    g=[row[:] for row in grid]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if g[i][j]==bg and (i in rows or j in cols): g[i][j]=new
    return g

